<?php
declare(strict_types=1);
if (PHP_SAPI!=='cli') {http_response_code(404);exit;}
ob_start();
define('KCRM_ROOT',dirname(__DIR__));
$fixture=sys_get_temp_dir().'/kosmoport-funnel-'.bin2hex(random_bytes(8));mkdir($fixture,0700,true);
$GLOBALS['funnel_config']=['environment'=>'test','app_key'=>bin2hex(random_bytes(32)),'base_path'=>'/kosmoport','storage_path'=>$fixture,'database'=>['driver'=>'sqlite_test','allow_test_driver'=>true,'path'=>':memory:'],'session'=>['name'=>'KPFUNNEL','secure'=>false,'same_site'=>'Lax','idle_seconds'=>1800,'absolute_seconds'=>43200],'website'=>['requests_enabled'=>false,'organizer_name'=>'Тестовый организатор','privacy_url'=>'https://example.invalid/privacy','public_url'=>'https://example.invalid/kosmoport']];
function crm_config(?string $key=null):mixed { $v=$GLOBALS['funnel_config'];if($key===null)return $v;foreach(explode('.',$key) as $part){if(!is_array($v)||!array_key_exists($part,$v))return null;$v=$v[$part];}return $v; }
function crm_storage_path(string $relative=''):string { $path=crm_config('storage_path').'/'.$relative;if(!is_dir($path))mkdir($path,0700,true);return $path; }
require KCRM_ROOT.'/app/core/http.php';require KCRM_ROOT.'/app/core/database.php';require KCRM_ROOT.'/app/core/session.php';require KCRM_ROOT.'/app/core/auth.php';require KCRM_ROOT.'/app/core/records.php';require KCRM_ROOT.'/app/core/migrations.php';
require KCRM_ROOT.'/app/website/content.php';require KCRM_ROOT.'/app/website/funnel.php';
$db=crm_db();foreach(crm_split_sql(file_get_contents(__DIR__.'/core-fixture.sql')) as $sql)$db->exec($sql);
$db->exec('CREATE TABLE kcrm_website(id INTEGER PRIMARY KEY,draft TEXT,published TEXT,revision INTEGER,published_revision INTEGER,updated_by TEXT,updated_at TEXT,published_at TEXT)');
// Explicit SQLite fixture. It is never applied or labelled as a MySQL migration.
$db->exec('CREATE TABLE kcrm_visit_requests(id TEXT PRIMARY KEY,dedupe_key TEXT NOT NULL UNIQUE,kind TEXT,name TEXT,contact TEXT,organization TEXT,guest_count INTEGER,visit_date TEXT,message TEXT,source TEXT,status TEXT,revision INTEGER,consent_at TEXT,privacy_url TEXT,ip_hash TEXT,created_at TEXT,updated_at TEXT)');
$_SERVER['REMOTE_ADDR']='192.0.2.1';$_SERVER['HTTP_HOST']='localhost';$_SERVER['SERVER_PORT']=80;
$passed=[];
function check_funnel(string $label,callable $fn):void {$fn();$GLOBALS['passed'][]=$label;}
function expect_funnel(bool $value,string $why='Assertion failed'):void {if(!$value)throw new RuntimeException($why);}
function rejects_funnel(callable $fn,int $status):void {try{$fn();}catch(CrmHttpException $e){expect_funnel($e->status===$status,'Expected '.$status.', got '.$e->status);return;}throw new RuntimeException('Expected rejection '.$status);}
function payload_funnel():array {return ['request_id'=>bin2hex(random_bytes(16)),'kind'=>'group','name'=>'Тестовая заявка','contact'=>'test@example.invalid','org'=>'Изолированная школа','quantity'=>20,'date'=>'2026-11-25','message'=>'Только тестовая запись','source'=>'fixture','consent'=>true,'website'=>''];}
check_funnel('intake is closed by default',fn()=>expect_funnel(!kp_requests_ready()));
$GLOBALS['funnel_config']['website']['requests_enabled']=true;
check_funnel('intake requires a published HTTPS privacy policy',function(){ $GLOBALS['funnel_config']['website']['privacy_url']='http://example.invalid';expect_funnel(!kp_requests_ready());$GLOBALS['funnel_config']['website']['privacy_url']='https://example.invalid/privacy';expect_funnel(kp_requests_ready());});
check_funnel('consent and contact validation do not save records',function(){ $p=payload_funnel();$p['consent']=false;rejects_funnel(fn()=>kp_visit_request($p),422);$p['consent']=true;$p['contact']='wrong';rejects_funnel(fn()=>kp_visit_request($p),422);expect_funnel((int)crm_db()->query('SELECT COUNT(*) FROM kcrm_visit_requests')->fetchColumn()===0);});
check_funnel('real event dates, counts and group organization are enforced',function(){foreach([['date'=>'2026-11-24'],['date'=>'2027-01-19'],['date'=>'2026-11-31'],['quantity'=>0],['quantity'=>201],['quantity'=>20.5],['org'=>''],['website'=>'bot']] as $bad){$p=array_replace(payload_funnel(),$bad);rejects_funnel(fn()=>kp_visit_request($p),422);}});
$p=payload_funnel();$saved=kp_visit_request($p);
check_funnel('request is persisted without pretending to be paid or reserved',function()use($saved){expect_funnel($saved['saved']===true&&$saved['paid']===false&&$saved['reserved']===false);$row=crm_db()->query('SELECT * FROM kcrm_visit_requests')->fetch();expect_funnel($row['guest_count']===20&&$row['contact']==='test@example.invalid'&&$row['consent_at']!==''&&$row['privacy_url']==='https://example.invalid/privacy');expect_funnel(strlen($row['ip_hash'])===64&&$row['ip_hash']!==$_SERVER['REMOTE_ADDR']);});
check_funnel('retry with the same request key saves once',function()use($p,$saved){$again=kp_visit_request($p);expect_funnel($again['id']===$saved['id']&&$again['duplicate']===true);expect_funnel((int)crm_db()->query('SELECT COUNT(*) FROM kcrm_visit_requests')->fetchColumn()===1);});
check_funnel('rate limit blocks the sixth new request and retains safe retry',function()use($p,$saved){for($i=0;$i<4;$i++)kp_visit_request(payload_funnel());rejects_funnel(fn()=>kp_visit_request(payload_funnel()),429);expect_funnel((int)crm_db()->query('SELECT COUNT(*) FROM kcrm_visit_requests')->fetchColumn()===5);expect_funnel(kp_visit_request($p)['id']===$saved['id']);});
check_funnel('anonymous and cashier cannot read submitted contacts',function(){$_SESSION=[];rejects_funnel(fn()=>kp_visit_requests(),401);$now=crm_now();foreach(['cashier','manager','editor'] as $role)crm_query('INSERT INTO kcrm_users(id,name,email,password_hash,role,created_at,updated_at) VALUES(?,?,?,?,?,?,?)',[$role,$role,$role.'@example.invalid','not-a-login-hash',$role,$now,$now]);$_SESSION=['user_id'=>'cashier','session_version'=>1,'authenticated_at'=>time(),'last_seen'=>time()];rejects_funnel(fn()=>kp_visit_requests(),403);});
check_funnel('manager receives requests and changes status with revision protection',function()use($saved){$_SESSION=['user_id'=>'manager','session_version'=>1,'authenticated_at'=>time(),'last_seen'=>time()];expect_funnel(kp_visit_requests()['total']===5);$next=kp_visit_request_status(['id'=>$saved['id'],'status'=>'contacted','expected_revision'=>1]);expect_funnel($next['revision']===2);rejects_funnel(fn()=>kp_visit_request_status(['id'=>$saved['id'],'status'=>'confirmed','expected_revision'=>1]),409);expect_funnel((int)crm_db()->query('SELECT COUNT(*) FROM kcrm_audit')->fetchColumn()===1);});
check_funnel('editor may read requests but cannot change their status',function()use($saved){$_SESSION=['user_id'=>'editor','session_version'=>1,'authenticated_at'=>time(),'last_seen'=>time()];expect_funnel(kp_visit_requests()['total']===5);rejects_funnel(fn()=>kp_visit_request_status(['id'=>$saved['id'],'status'=>'confirmed','expected_revision'=>2]),403);});
check_funnel('valid CSRF token and same origin are required',function(){ $token=crm_csrf_token();rejects_funnel(fn()=>crm_check_csrf(str_repeat('0',64)),403);$_SERVER['HTTP_ORIGIN']='https://other.invalid';rejects_funnel(fn()=>crm_check_csrf($token),403);$_SERVER['HTTP_ORIGIN']='http://localhost';crm_check_csrf($token);});
check_funnel('catalog sales stay closed even when the legacy scalar price and checkout URL are enabled',function(){ $c=kp_default_content();expect_funnel(kp_checkout_target($c)===null);$c['tickets']['sales_open']=true;$c['tickets']['price']=800;$c['tickets']['checkout_url']='http://example.invalid/pay';expect_funnel(kp_checkout_target($c)===null);$c['tickets']['checkout_url']='https://user:pass@example.invalid/pay';expect_funnel(kp_checkout_target($c)===null);$c['tickets']['checkout_url']='https://example.invalid/pay';expect_funnel(kp_checkout_target($c)===null);expect_funnel(!kp_catalog_live_sales_ready());});
check_funnel('missing migration closes intake and gives staff a controlled 503',function()use($saved){$_SESSION=['user_id'=>'manager','session_version'=>1,'authenticated_at'=>time(),'last_seen'=>time()];crm_db()->exec('ALTER TABLE kcrm_visit_requests RENAME TO kcrm_visit_requests_fixture_hidden');try{expect_funnel(!kp_requests_ready());rejects_funnel(fn()=>kp_visit_requests(),503);rejects_funnel(fn()=>kp_visit_request_status(['id'=>$saved['id'],'status'=>'contacted','expected_revision'=>2]),503);}finally{crm_db()->exec('ALTER TABLE kcrm_visit_requests_fixture_hidden RENAME TO kcrm_visit_requests');}});
session_write_close();ob_end_clean();
foreach($passed as $name)echo 'PASS '.$name.PHP_EOL;
echo 'Website funnel: '.count($passed).' checks passed; disposable SQLite records only.'.PHP_EOL;
